import{_ as e,z as a,m as o,ap as r}from"./chunks/framework.bQJNM8pB.js";const n="/adapter-yunhupro/assets/058e81af-eabf-44a8-9227-f023afd69711.CK9GXaiH.png",s="/adapter-yunhupro/assets/dee633e3-6d9b-4e5d-9438-a8c2c8501647.DnajvuuY.png",d="/adapter-yunhupro/assets/screenshot_2026-04-25_21-03-50.kGPFCRRH.png",f=JSON.parse('{"title":"首次接入指南","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/firstime/start.md","filePath":"markdown/firstime/start.md","lastUpdated":1786201797000}'),i={name:"markdown/firstime/start.md"};function l(p,t,h,c,b,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="首次接入指南" tabindex="-1">首次接入指南 <a class="header-anchor" href="#首次接入指南" aria-label="Permalink to &quot;首次接入指南&quot;">​</a></h1><h2 id="首次接入和配置" tabindex="-1">首次接入和配置 <a class="header-anchor" href="#首次接入和配置" aria-label="Permalink to &quot;首次接入和配置&quot;">​</a></h2><p>本指南将引导您完成 <code>adapter-yunhupro</code> 在 Koishi 中的首次接入和配置。</p><h2 id="_1-在云湖平台创建机器人" tabindex="-1">1. 在云湖平台创建机器人 <a class="header-anchor" href="#_1-在云湖平台创建机器人" aria-label="Permalink to &quot;1. 在云湖平台创建机器人&quot;">​</a></h2><blockquote><p><strong>教程以 云湖Windows版客户端 演示</strong></p></blockquote><p>访问 <a href="https://www.yhchat.com/" target="_blank" rel="noreferrer">云湖官网</a> ，下载并安装对应的客户端。</p><p>注册并登录账号后，进入设置页面，创建一个新的机器人。</p><p>根据页面提示，完成机器人的 头像、名称、简介 的配置。</p><p><img src="'+n+'" alt="云湖后台"></p><h2 id="_2-获取机器人-token" tabindex="-1">2. 获取机器人 Token <a class="header-anchor" href="#_2-获取机器人-token" aria-label="Permalink to &quot;2. 获取机器人 Token&quot;">​</a></h2><p>打开 <strong>机器人控制台</strong>，复制机器人的 Token：</p><ul><li><strong>机器人 Token</strong>：这是与云湖 API 通信的密钥。</li></ul><p><img src="'+s+'" alt="获取机器人Token"></p><h2 id="_2-1-配置订阅事件" tabindex="-1">2.1 配置订阅事件 <a class="header-anchor" href="#_2-1-配置订阅事件" aria-label="Permalink to &quot;2.1 配置订阅事件&quot;">​</a></h2><p>打开 <strong>机器人控制台</strong>，配置机器人接收的事件：</p><blockquote><p>可以全部都勾选上</p></blockquote><p><img src="'+d+'" alt="alt"></p><h2 id="_3-连接方式要求" tabindex="-1">3. 连接方式要求 <a class="header-anchor" href="#_3-连接方式要求" aria-label="Permalink to &quot;3. 连接方式要求&quot;">​</a></h2><p>云湖平台支持两种连接方式：</p><h3 id="websocket-方式-推荐" tabindex="-1">WebSocket 方式（推荐） <a class="header-anchor" href="#websocket-方式-推荐" aria-label="Permalink to &quot;WebSocket 方式（推荐）&quot;">​</a></h3><p><strong>无需公网 IP</strong>，通过 WebSocket 长连接接收事件推送。</p><p>这是默认且推荐的连接方式，配置简单，无需额外的网络配置。</p><h3 id="webhook-方式" tabindex="-1">Webhook 方式 <a class="header-anchor" href="#webhook-方式" aria-label="Permalink to &quot;Webhook 方式&quot;">​</a></h3><p>通过 Webhook 接收事件推送，<strong>需要公网访问能力</strong>。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果选择 Webhook 方式，您需要具备<strong>以下条件之一</strong>：</p><ul><li>拥有一个公网 IPv4 或 IPv6 地址。</li><li>使用内网穿透服务（如 frp, Ngrok, Cloudflare Tunnel 等）将您的本地 Koishi 服务暴露到公网。</li></ul></div><h3 id="连接方式对比" tabindex="-1">连接方式对比 <a class="header-anchor" href="#连接方式对比" aria-label="Permalink to &quot;连接方式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>WebSocket</th><th>Webhook</th></tr></thead><tbody><tr><td>公网 IP</td><td>✅ 不需要</td><td>⚠️ 需要</td></tr><tr><td>配置难度</td><td>✅ 简单</td><td>⚠️ 复杂</td></tr><tr><td>多机器人</td><td>✅ 无限制</td><td>⚠️ 需要不同路径</td></tr><tr><td>消息混乱</td><td>✅ 不会</td><td>⚠️ 路径相同时会</td></tr><tr><td>推荐程度</td><td>✅ 推荐</td><td>⚠️ 有特殊需求才用</td></tr></tbody></table><p><strong>推荐使用 WebSocket 方式</strong>，除非您有特殊需求必须使用 Webhook。</p><h2 id="_4-选择接入方式-继续阅读对应教程" tabindex="-1">4. 选择接入方式，继续阅读对应教程 <a class="header-anchor" href="#_4-选择接入方式-继续阅读对应教程" aria-label="Permalink to &quot;4. 选择接入方式，继续阅读对应教程&quot;">​</a></h2><p>完成以上公共前置配置后，根据您的实际部署选择对应的教程继续阅读：</p><div style="display:flex;flex-wrap:wrap;gap:16px;justify-content:space-between;align-items:stretch;margin:16px 0;"><a href="./start-webhook" style="flex:1 1 46%;min-width:240px;text-decoration:none;display:flex;flex-direction:column;justify-content:space-between;border:1px solid var(--vp-c-divider);border-radius:12px;padding:16px 20px;transition:border-color .2s,border-style .2s;"><span style="font-size:15px;font-weight:600;color:var(--vp-c-brand);margin-top:4px;">Webhook 方式接入教程</span></a><a href="./start-websocket" style="flex:1 1 46%;min-width:240px;text-decoration:none;display:flex;flex-direction:column;justify-content:space-between;border:1px solid var(--vp-c-divider);border-radius:12px;padding:16px 20px;text-align:right;transition:border-color .2s,border-style .2s;"><span style="font-size:15px;font-weight:600;color:var(--vp-c-brand);margin-top:4px;">WebSocket 方式接入教程（推荐）</span></a></div>',31)])])}const m=e(i,[["render",l]]);export{f as __pageData,m as default};
